INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4108105, 588405, 75713, '<td valign="top">very well done... I like the blue ... the model is in crisp focus.. nicely photographed</td>', 'very well done... I like the blue ... the model is in crisp focus.. nicely photographed', '2007-09-22 01:09:13.000000', NULL, 1),
(4108115, 588808, 48697, '<td valign="top">looks oof.</td>', 'looks oof.', '2007-09-22 01:16:44.000000', NULL, 1),
(4108145, 588787, 75713, '<td valign="top">Something about this shot evokes, in me, feelings of long ago... times when children played later in the night... the sharing of secrets away from the ears of parents... your entry tells a story and to me that is important</td>', 'Something about this shot evokes, in me, feelings of long ago... times when children played later in the night... the sharing of secrets away from the ears of parents... your entry tells a story and to me that is important', '2007-09-22 02:19:10.000000', NULL, 1),
(4108147, 588974, 75713, '<td valign="top">nicely photographed... I like the composition - the sun being blacked by the tail of the plane made this shot</td>', 'nicely photographed... I like the composition - the sun being blacked by the tail of the plane made this shot', '2007-09-22 02:20:03.000000', NULL, 1),
(4108149, 588522, 75713, '<td valign="top">I had to look twice as I thought the sand was snow at first... I like the gentle hues in the sky.</td>', 'I had to look twice as I thought the sand was snow at first... I like the gentle hues in the sky.', '2007-09-22 02:21:22.000000', NULL, 1),
(4108150, 588652, 75713, '<td valign="top">I really like how the models hand seems to be fading into the sun... crisp shot nicely composed - great title</td>', 'I really like how the models hand seems to be fading into the sun... crisp shot nicely composed - great title', '2007-09-22 02:22:33.000000', NULL, 1),
(4108151, 588854, 75713, '<td valign="top">How beautiful this scene is... a nice break from the more dramatic colors in many of the sunsets - love the clouds... all in all very well photographed</td>', 'How beautiful this scene is... a nice break from the more dramatic colors in many of the sunsets - love the clouds... all in all very well photographed', '2007-09-22 02:23:53.000000', NULL, 1),
