(4350278, 587699, 63269, '<td valign="top">Glorious. Sunset shots have been way overdone, of course. But <i>this </i>sunset shot has an unusual depth and richness to the colors that makes it just fantastic. :) I get a thrill looking at those vibrant peachy hues intertangled in the tree branches. Lovely.</td>', 'Glorious. Sunset shots have been way overdone, of course. But this sunset shot has an unusual depth and richness to the colors that makes it just fantastic. :) I get a thrill looking at those vibrant peachy hues intertangled in the tree branches. Lovely.', '2008-01-01 15:10:00.000000', NULL, 0),
(4443279, 587338, 23484, '<td valign="top">Very nice urban silhouette.</td>', 'Very nice urban silhouette.', '2008-01-31 11:46:49.000000', NULL, 0),
